package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportPublicationRepository.Publication;
import cn.mop.domain.assetexport.AssetExportJobState.Filters;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual designated PostgreSQL. Fake storage callbacks are always rolled back; no fake inbox message is committed. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresExportInboxIntegrationTest {
 static final String TENANT="55000000-0000-4000-8000-000000000001";static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository jobs;static PostgresExportInboxRepository inbox;static ObjectMapper mapper;static String admin;
 @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);jobs=new PostgresAssetExportRepository(pool,platform);inbox=new PostgresExportInboxRepository(pool,platform);admin=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("padmin")).isPresent()).findFirst().orElseThrow().id();}
 @AfterAll static void close(){if(pool!=null)pool.close();}
 static Access access(){return new Access(admin,TENANT,platform.membership(admin,TENANT).orElseThrow().permissionVersion(),"inbox-pg-"+UUID.randomUUID());}
 static Object command(Access a,String route,String key,Supplier<Object> action){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),a.permissionVersion(),()->{},action);}
 record Prepared(Job job,AssetExportPreparedFile file){}
 static Prepared prepare()throws Exception{var a=access();Job j=mapper.convertValue(command(a,"POST /integration/inbox-prepare",UUID.randomUUID().toString(),()->jobs.accept(a,new Filters(null,null,null,"MOP-FAKE-PG-INBOX-"+UUID.randomUUID()))),Job.class);var claim=jobs.claim(j.id(),"inbox-structure-test",Duration.ofSeconds(5)).orElseThrow();var work=jobs.loadWork(claim);var f=AssetExportPreparedFile.create(claim.command(),"b".repeat(64),0,work.databaseNow(),new byte[]{1,2,3});jobs.prepare(claim,f);try(var c=pool.getConnection();var s=c.prepareStatement("SELECT pg_sleep(GREATEST(0,EXTRACT(EPOCH FROM (?::timestamptz-clock_timestamp())))+0.02)")){s.setObject(1,claim.leaseUntil().atOffset(ZoneOffset.UTC));s.execute();}return new Prepared(jobs.get(a,j.id()),f);}
 static Publication publish(Prepared p,String key){var a=access();return mapper.convertValue(command(a,"POST /integration/inbox-publish/"+p.job().id(),key,()->{var published=jobs.publish(a,p.job().id(),p.job().version(),p.file().encoding().fileSha256(),(k,f)->{});inbox.recordPublished(a,published);return published;}),Publication.class);}
 static final class Rollback extends RuntimeException{}
 static void rolling(Prepared p,BiConsumer<Connection,Publication> checks){assertThrows(Rollback.class,()->platform.identityTransaction(c->{var pub=publish(p,UUID.randomUUID().toString());checks.accept(c,pub);throw new Rollback();}));assertEquals(p.job(),jobs.get(access(),p.job().id()));try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM mop_export_inbox WHERE job_id=?::uuid")){s.setString(1,p.job().id());try(var r=s.executeQuery()){r.next();assertEquals(0,r.getInt(1));}}catch(SQLException e){throw new RuntimeException(e);}}
 static ExportInboxRepository.Message mark(Access a,String id,long v,String key){return mapper.convertValue(command(a,"POST /integration/inbox-read/"+id,key,()->{inbox.authorizeRead(a,id);return inbox.markRead(a,id,v);}),ExportInboxRepository.Message.class);}
 static void deniedSql(Connection c,String sql){try{var sp=c.setSavepoint();try(var s=c.createStatement()){assertThrows(SQLException.class,()->s.execute(sql));}finally{c.rollback(sp);}}catch(SQLException e){throw new RuntimeException(e);}}
 @Test void actualSchemaAndRestrictedRoleAreReady()throws Exception{try(var c=pool.getConnection()){ExportInboxSchemaVerifier.verify(c);}assertTrue(inbox.readinessProblems().isEmpty());}
 @Test void publicationMessageAndReadAreAtomicAndOriginalExpiryIsRetained()throws Exception{var p=prepare();rolling(p,(c,pub)->{String key=UUID.randomUUID().toString();var a=access();var first=mark(a,p.job().id(),0,key);assertEquals(1,first.version());assertNotNull(first.readAt());assertEquals(pub.storedAt(),first.issuedAt());assertEquals(pub.storedAt().plusSeconds(900),first.expiresAt());assertEquals(first,mark(a,p.job().id(),0,key));});}
 @Test void publicationReplayDoesNotInsertAnotherMessage()throws Exception{var p=prepare();assertThrows(Rollback.class,()->platform.identityTransaction(c->{String key=UUID.randomUUID().toString();var first=publish(p,key);assertEquals(first,publish(p,key));try(var s=c.prepareStatement("SELECT count(*) FROM mop_export_inbox WHERE job_id=?::uuid")){s.setString(1,p.job().id());try(var r=s.executeQuery()){r.next();assertEquals(1,r.getInt(1));}}catch(SQLException e){throw new RuntimeException(e);}throw new Rollback();}));assertEquals(p.job(),jobs.get(access(),p.job().id()));}
 @Test void staleReadVersionConflictsAndReadStateCannotBeCleared()throws Exception{var p=prepare();rolling(p,(c,pub)->{var a=access();var first=mark(a,p.job().id(),0,UUID.randomUUID().toString());assertEquals(409,assertThrows(DomainException.class,()->mark(a,p.job().id(),0,UUID.randomUUID().toString())).status);assertEquals(first,mark(a,p.job().id(),1,UUID.randomUUID().toString()));deniedSql(c,"UPDATE mop_export_inbox SET version=0,read_at=NULL WHERE job_id='"+p.job().id()+"'");});}
 @Test void crossTenantAndOtherCreatorReadAcknowledgementsReturn404()throws Exception{var p=prepare();rolling(p,(c,pub)->{String tenant=platform.allowedTenants(admin).stream().map(Tenant::id).filter(t->!t.equals(TENANT)).findFirst().orElseThrow();var m=platform.membership(admin,tenant).orElseThrow();Access otherTenant=new Access(admin,tenant,m.permissionVersion(),"inbox-other-tenant");assertEquals(404,assertThrows(DomainException.class,()->mark(otherTenant,p.job().id(),0,UUID.randomUUID().toString())).status);String other=platform.users().stream().filter(u->!u.id().equals(admin)&&platform.membership(u.id(),TENANT).filter(x->x.role().equals("msp")).isPresent()).findFirst().orElseThrow().id();var membership=platform.membership(other,TENANT).orElseThrow();assertEquals(404,assertThrows(DomainException.class,()->mark(new Access(other,TENANT,membership.permissionVersion(),"other-creator"),p.job().id(),0,UUID.randomUUID().toString())).status);});}
 @Test void databasePreventsMessageRewriteDeleteDuplicateAndFutureRead()throws Exception{var p=prepare();rolling(p,(c,pub)->{String id=p.job().id();deniedSql(c,"UPDATE mop_export_inbox SET expires_at=expires_at+interval '1 minute' WHERE job_id='"+id+"'");deniedSql(c,"DELETE FROM mop_export_inbox WHERE job_id='"+id+"'");deniedSql(c,"UPDATE mop_export_inbox SET version=1,read_at=clock_timestamp()+interval '1 hour' WHERE job_id='"+id+"'");deniedSql(c,"INSERT INTO mop_export_inbox SELECT * FROM mop_export_inbox WHERE job_id='"+id+"'");});}
 @Test void fabricatedMessageBeforePublicationIsRejectedByDatabase()throws Exception{var p=prepare();try(var c=pool.getConnection()){c.setAutoCommit(false);deniedSql(c,"INSERT INTO mop_export_inbox(job_id,tenant_id,recipient_id,permission_version,published_version,file_sha256,issued_at,expires_at) SELECT id,tenant_id,created_by,permission_version,version,file_sha256,updated_at,updated_at+interval '15 minutes' FROM mop_asset_export_job WHERE id='"+p.job().id()+"'");c.rollback();}}
 @Test void standaloneWriteAndMalformedPaginationFailClosed(){assertThrows(IllegalStateException.class,()->inbox.markRead(access(),UUID.randomUUID().toString(),0));for(int n:List.of(0,51))assertEquals(400,assertThrows(DomainException.class,()->inbox.list(access(),n,null,null,false)).status);assertEquals(400,assertThrows(DomainException.class,()->inbox.list(access(),20,Instant.now(),null,false)).status);}
 @Test void rolledBackPublicationNeverAppearsInStandaloneInbox()throws Exception{var p=prepare();rolling(p,(c,pub)->{});assertFalse(inbox.list(access(),50,null,null,false).items().stream().anyMatch(m->m.jobId().equals(p.job().id())));}
}
